/bin/sh -lc "python3 - <<'PY'
import itertools
moves=['G->R','S->K','K->S']
for perm in itertools.permutations(moves):
 labels={'R':'C','B':'A','G':'B'} # physical A key, B coin, C marble after label swap (mapping label->phys)
 cont={'A':{'K'},'B':{'S'},'C':{'G'}}
 no=[]
 def do(m):
  obj,target=m.split('->'); src=next(p for p,v in cont.items() if obj in v)
  if target in labels: dst=labels[target]
  else: dst=next(p for p,v in cont.items() if target in v)
  if src==dst:no.append(m)
  else:cont[src].remove(obj);cont[dst].add(obj)
 do(perm[0]); cont[labels['R']],cont[labels['G']]=cont[labels['G']],cont[labels['R']]
 do(perm[1]); cont[labels['B']],cont[labels['G']]=cont[labels['G']],cont[labels['B']]
 do(perm[2])
 print(perm,'noop',no,'final',{l:''.join(sorted(cont[p])) or '-' for l,p in labels.items()})
PY"

